class Solution:
    def maxNumber(self, nums1, nums2, k):
        from itertools import combinations
        def subs(a, t):
            return [list(c) for c in combinations(a, t)]
        best = []
        for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
            for s1 in subs(nums1, i):
                for s2 in subs(nums2, k - i):
                    cand = self.merge(s1, s2)
                    if cand > best:
                        best = cand
        return best
    def merge(self, a, b):
        res = []
        while a or b:
            if a > b:
                res.append(a.pop(0))
            else:
                res.append(b.pop(0))
        return res

