class Solution {
public:
    vector<int> maxNumber(vector<int>& nums1, vector<int>& nums2, int k) {
        vector<int> best;
        int m = nums1.size(), n = nums2.size();
        vector<int> idx1, idx2;
        function<void(int,int,int,vector<int>&)> gen = [&](int arr, int start, int need, vector<int>& cur){
            if (need == 0) { rec(arr, cur, nums1, nums2, k, best); return; }
            const vector<int>& src = arr ? nums2 : nums1;
            for (int j = start; j <= (int)src.size() - need; j++) {
                cur.push_back(src[j]);
                gen(arr, j + 1, need - 1, cur);
                cur.pop_back();
            }
        };
        for (int i = max(0, k - n); i <= min(k, m); i++) {
            vector<int> c1, c2;
            gen(0, 0, i, c1);
            (void)c2;
        }
        return best;
    }
private:
    void rec(int arr, vector<int>& cur, vector<int>& n1, vector<int>& n2, int k, vector<int>& best) {
        // collect chosen from first array, then enumerate second
        static vector<int> first;
        if (arr == 0) { first = cur; vector<int> e; gen2(0, 0, k - (int)cur.size(), e, n2, first, best); return; }
    }
    void gen2(int start, int depth, int need, vector<int>& cur, vector<int>& src, vector<int>& first, vector<int>& best) {
        if (need == 0) {
            vector<int> a = first, b = cur, res;
            while (!a.empty() || !b.empty()) {
                if (a > b) { res.push_back(a[0]); a.erase(a.begin()); }
                else { res.push_back(b[0]); b.erase(b.begin()); }
            }
            if (res > best) best = res;
            return;
        }
        for (int j = start; j <= (int)src.size() - need; j++) {
            cur.push_back(src[j]);
            gen2(j + 1, depth + 1, need - 1, cur, src, first, best);
            cur.pop_back();
        }
    }
};

