class Solution {
    private int[] best;
    public int[] maxNumber(int[] nums1, int[] nums2, int k) {
        best = new int[k];
        for (int i = Math.max(0, k - nums2.length); i <= Math.min(k, nums1.length); i++) {
            List<Integer> c1 = new ArrayList<>();
            gen(nums1, 0, i, c1, nums2, k);
        }
        return best;
    }
    private void gen(int[] src, int start, int need, List<Integer> cur, int[] other, int k) {
        if (need == 0) {
            List<Integer> c2 = new ArrayList<>();
            gen2(other, 0, k - cur.size(), c2, new ArrayList<>(cur));
            return;
        }
        for (int j = start; j <= src.length - need; j++) {
            cur.add(src[j]);
            gen(src, j + 1, need - 1, cur, other, k);
            cur.remove(cur.size() - 1);
        }
    }
    private void gen2(int[] src, int start, int need, List<Integer> cur, List<Integer> first) {
        if (need == 0) {
            int[] res = merge(first, cur, best.length);
            if (greater(res, best)) best = res;
            return;
        }
        for (int j = start; j <= src.length - need; j++) {
            cur.add(src[j]);
            gen2(src, j + 1, need - 1, cur, first);
            cur.remove(cur.size() - 1);
        }
    }
    private int[] merge(List<Integer> a, List<Integer> b, int k) {
        int[] r = new int[k]; int p = 0, i = 0, j = 0;
        while (p < k) {
            if (greaterList(a, i, b, j)) r[p++] = a.get(i++);
            else r[p++] = b.get(j++);
        }
        return r;
    }
    private boolean greaterList(List<Integer> a, int i, List<Integer> b, int j) {
        while (i < a.size() && j < b.size() && a.get(i).equals(b.get(j))) { i++; j++; }
        return j == b.size() || (i < a.size() && a.get(i) > b.get(j));
    }
    private boolean greater(int[] a, int[] b) {
        for (int i = 0; i < a.length; i++) if (a[i] != b[i]) return a[i] > b[i];
        return false;
    }
}

