var maxNumber = function(nums1, nums2, k) {
    let best = [];
    const cmp = (a, b) => {
        for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] > b[i];
        return false;
    };
    const merge = (a, b) => {
        const res = [];
        while (a.length || b.length) {
            let takeA;
            if (!b.length) takeA = true;
            else if (!a.length) takeA = false;
            else {
                let i = 0;
                while (i < a.length && i < b.length && a[i] === b[i]) i++;
                takeA = i === b.length || (i < a.length && a[i] > b[i]);
            }
            res.push(takeA ? a.shift() : b.shift());
        }
        return res;
    };
    const gen = (src, start, need, cur, other, isFirst) => {
        if (need === 0) {
            if (isFirst) gen(other, 0, k - cur.length, [], [...cur], false);
            else {
                const cand = merge([...cur], other);
                if (cmp(cand, best)) best = cand;
            }
            return;
        }
        for (let j = start; j <= src.length - need; j++) {
            cur.push(src[j]);
            gen(src, j + 1, need - 1, cur, other, isFirst);
            cur.pop();
        }
    };
    for (let i = Math.max(0, k - nums2.length); i <= Math.min(k, nums1.length); i++) {
        gen(nums1, 0, i, [], nums2, true);
    }
    return best;
};

