            st = []
            drop = len(a) - t
            for x in a:
                while drop and st and st[-1] < x:
                    st.pop(); drop -= 1
                st.append(x)
            return st[:t]
        def merge(a, b):
            res = []
            i = j = 0
            while i < len(a) or j < len(b):
                if a[i:] > b[j:]:
                    res.append(a[i]); i += 1
                else:
                    res.append(b[j]); j += 1
            return res
        best = []
        for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
            cand = merge(pick(nums1, i), pick(nums2, k - i))
            if cand > best:
                best = cand
        return best

