class Solution {
public:
    vector<int> maxNumber(vector<int>& nums1, vector<int>& nums2, int k) {
        int m = nums1.size(), n = nums2.size();
        vector<int> best;
        for (int i = max(0, k - n); i <= min(k, m); i++) {
            auto s1 = pick(nums1, i), s2 = pick(nums2, k - i);
            auto cand = merge(s1, s2);
            if (cand > best) best = cand;
        }
        return best;
    }
private:
    vector<int> pick(vector<int>& a, int t) {
        vector<int> st;
        int drop = a.size() - t;
        for (int x : a) {
            while (drop > 0 && !st.empty() && st.back() < x) { st.pop_back(); drop--; }
            st.push_back(x);
        }
        st.resize(t);
        return st;
    }
    vector<int> merge(vector<int>& a, vector<int>& b) {
        vector<int> res;
        int i = 0, j = 0;
        while (i < a.size() || j < b.size()) {
            if (greater(a, i, b, j)) res.push_back(a[i++]);
            else res.push_back(b[j++]);
        }
        return res;
    }
    bool greater(vector<int>& a, int i, vector<int>& b, int j) {
        while (i < a.size() && j < b.size() && a[i] == b[j]) { i++; j++; }
        return j == b.size() || (i < a.size() && a[i] > b[j]);
    }
};

