class Solution {
    public int[] maxNumber(int[] nums1, int[] nums2, int k) {
        int m = nums1.length, n = nums2.length;
        int[] best = new int[k];
        for (int i = Math.max(0, k - n); i <= Math.min(k, m); i++) {
            int[] s1 = pick(nums1, i), s2 = pick(nums2, k - i);
            int[] cand = merge(s1, s2);
            if (greater(cand, best)) best = cand;
        }
        return best;
    }
    private int[] pick(int[] a, int t) {
        int[] st = new int[t];
        int top = 0, drop = a.length - t;
        for (int x : a) {
            while (drop > 0 && top > 0 && st[top - 1] < x) { top--; drop--; }
            if (top < t) st[top++] = x;
        }
        return st;
    }
    private int[] merge(int[] a, int[] b) {
        int[] res = new int[a.length + b.length];
        int i = 0, j = 0, p = 0;
        while (i < a.length || j < b.length) {
            if (greaterFrom(a, i, b, j)) res[p++] = a[i++];
            else res[p++] = b[j++];
        }
        return res;
    }
    private boolean greaterFrom(int[] a, int i, int[] b, int j) {
        while (i < a.length && j < b.length && a[i] == b[j]) { i++; j++; }
        return j == b.length || (i < a.length && a[i] > b[j]);
    }
    private boolean greater(int[] a, int[] b) {
        for (int i = 0; i < a.length; i++) if (a[i] != b[i]) return a[i] > b[i];
        return false;
    }
}

